  // Instance normalization per channel (over spatial dims 1,2 for each batch and channel)
  // Calculate mean over spatial dimensions (dims 1,2)
  %zero_const = stablehlo.constant dense<0.0> : tensor<f32>
  %mean_reduced = "stablehlo.reduce"(%reshaped_for_norm, %zero_const) ({ 
  ^bb0(%arg_a: tensor<f32>, %arg_b: tensor<f32>): 
    %add_mean = stablehlo.add %arg_a, %arg_b : tensor<f32>
    "stablehlo.return"(%add_mean) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1, 2>} : (tensor<6x1x1x7xf32>, tensor<f32>) -> tensor<6x7xf32>

