  %mean_reshaped = stablehlo.reshape %mean_reduced : (tensor<6x7xf32>) -> tensor<6x1x1x7xf32>

  // Calculate variance: mean((x - mean)^2)
  %diff_from_mean = stablehlo.subtract %reshaped_for_norm, %mean_reshaped : tensor<6x1x1x7xf32>
  %squared_diff = stablehlo.multiply %diff_from_mean, %diff_from_mean : tensor<6x1x1x7xf32>
  %var_reduced = "stablehlo.reduce"(%squared_diff, %zero_const) ({ 
  ^bb0(%arg_a: tensor<f32>, %arg_b: tensor<f32>): 
    %add_var = stablehlo.add %arg_a, %arg_b : tensor<f32>
    "stablehlo.return"(%add_var) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1, 2>} : (tensor<6x1x1x7xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Divide by number of elements and add epsilon (1 + 1e-5)
  %one_const = stablehlo.constant dense<1.0> : tensor<f32>
  %var_reshaped = stablehlo.reshape %var_reduced : (tensor<6x7xf32>) -> tensor<6x1x1x7xf32>
