  %epsilon_broadcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x1x7xf32>
  %var_plus_epsilon = stablehlo.add %var_reshaped, %epsilon_broadcast : tensor<6x1x1x7xf32>
