  %added_result = stablehlo.add %norm_result, %arg3 : tensor<6x7xf32>

  // Step 4: Multiply by y
  %final_result = stablehlo.multiply %added_result, %arg3 : tensor<6x7xf32>

  return %final_result : tensor<6x7xf32>
}

