func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Step 1: Linear transformation - x @ weight.T + bias
  // arg2 shape: [6,7], arg0 shape: [7,7] -> result shape: [6,7]
  %0 = "stablehlo.dot_general"(%arg2, %arg0) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias
  %1 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %2 = "stablehlo.add"(%0, %1) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

