  %mean_init = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %4 = "stablehlo.reduce"(%3, %mean_init) ({ ^bb0(%arg4: tensor<f32>, %arg5: tensor<f32>): 
    %sum = "stablehlo.add"(%arg4, %arg5) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 3>} : (tensor<6x1x1x7xf32>, tensor<f32>) -> tensor<6x1x1xf32>

  // Divide by 7 to get mean
  %count = "stablehlo.constant"() {value = dense<7.0> : tensor<f32>} : () -> tensor<f32>
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%count) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x1xf32>
  %5 = "stablehlo.divide"(%4, %mean_broadcast) : (tensor<6x1x1xf32>, tensor<6x1x1xf32>) -> tensor<6x1x1xf32>

