  %mean_expanded = "stablehlo.broadcast_in_dim"(%5) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<6x1x1xf32>) -> tensor<6x1x1x7xf32>
  %input_reshaped = "stablehlo.broadcast_in_dim"(%3) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x1x7xf32>) -> tensor<6x1x1x7xf32>

