func.func @main(%arg0: tensor<16x1x1x1xf32>, %arg1: tensor<16x3x3x3x3xf32>, %arg2: tensor<16xf32>, %arg3: tensor<6x3x16x7x7xf32>) -> tensor<6x14x5x5xf32> {
  %cst = stablehlo.constant dense<1.000000e+00> : tensor<f32>
  %cst_0 = stablehlo.constant dense<-1.000000e+00> : tensor<f32>
  %cst_1 = stablehlo.constant dense<0.000000e+00> : tensor<f32>
  %cst_2 = stablehlo.constant dense<1.414213e+00> : tensor<f32>

  // Conv3D: conv(x)
  // Input: tensor<6x3x16x7x7xf32> weight: tensor<16x3x3x3x3xf32> bias: tensor<16xf32>
  // Output should be: tensor<6x16x14x5x5xf32> 
  %0 = "stablehlo.convolution"(%arg3, %arg1) { 
    window_strides = array<i64: 1, 1, 1>, 
    padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
