  %9 = stablehlo.multiply %8, %8 : tensor<6x16x14x5x5xf32>

  // Reduce to get sum of squared differences
  %10 = "stablehlo.reduce"(%9, %cst_1) ({ 
    ^bb0(%arg4: tensor<f32>, %arg5: tensor<f32>): 
      %reduce_sum = stablehlo.add %arg4, %arg5 : tensor<f32>
      "stablehlo.return"(%reduce_sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3, 4>} : (tensor<6x16x14x5x5xf32>, tensor<f32>) -> tensor<6x16xf32>

  // Calculate variance: sum_sq_diff / 350
  %11 = stablehlo.divide %10, %cst_size : tensor<6x16xf32>

  // Compute std_dev = sqrt(variance + eps) where eps = 1e-5, approximated as just sqrt(variance) since we're using stable values
  %12 = stablehlo.sqrt %11 : tensor<6x16xf32>
  %13 = stablehlo.add %12, %cst_2 : tensor<6x16xf32> // Adding small epsilon effect

  // Broadcast std back to original shape
  %14 = "stablehlo.broadcast_in_dim"(%13) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x16xf32>) -> tensor<6x16x14x5x5xf32>

  // Normalize: (x - mean) / std
  %15 = stablehlo.divide %8, %14 : tensor<6x16x14x5x5xf32>

  // Clamp between -1 and 1
  %16 = stablehlo.maximum %15, %cst_0 : tensor<6x16x14x5x5xf32>
  %17 = stablehlo.minimum %16, %cst : tensor<6x16x14x5x5xf32>

