  %18 = stablehlo.multiply %17, %3 : tensor<6x16x14x5x5xf32>

  // Max over channel dimension (dim=1) to get tensor<6x14x5x5xf32>
  %19 = "stablehlo.reduce"(%18, %cst_0) ({ 
    ^bb0(%arg4: tensor<f32>, %arg5: tensor<f32>): 
      %reduce_max = stablehlo.maximum %arg4, %arg5 : tensor<f32>
      "stablehlo.return"(%reduce_max) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x16x14x5x5xf32>, tensor<f32>) -> tensor<6x14x5x5xf32>

  return %19 : tensor<6x14x5x5xf32>
}

func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c1 = stablehlo.constant dense<1.0> : tensor<f32>
  %c_epsilon = stablehlo.constant dense<1e-05> : tensor<f32>

  // Step 1: Matrix multiplication - x @ matmul.weight.T + matmul.bias
  // x shape: (16, 16), matmul.weight shape: (16, 16)
  // For matmul: (16, 16) @ (16, 16) -> (16, 16)
  // contracting dim 1 of lhs with dim 0 of rhs
  %matmul_result = "stablehlo.dot_general"(%arg5, %arg1) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add matmul bias - need to broadcast from (16,) to (16, 16)
  %matmul_bias_broadcasted = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %linear_result = stablehlo.add %matmul_result, %matmul_bias_broadcasted : tensor<16x16xf32>

  // Step 2: Swish activation - sigmoid(x) * x
  %neg_linear = stablehlo.negate %linear_result : tensor<16x16xf32>
  %exp_neg_linear = stablehlo.exponential %neg_linear : tensor<16x16xf32>
  %sigmoid_denom = stablehlo.add %exp_neg_linear, %c1 : tensor<16x16xf32>
  %sigmoid_result = stablehlo.divide %c1, %sigmoid_denom : tensor<16x16xf32>
  %swish_result = stablehlo.multiply %linear_result, %sigmoid_result : tensor<16x16xf32>

  // Step 3: Add bias term
  %bias_broadcasted = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %biased_result = stablehlo.add %swish_result, %bias_broadcasted : tensor<16x16xf32>

  // Step 4: Group Normalization with batch statistics
  // GroupNorm reshapes to (batch, num_groups, features_per_group)
  // Here we have 16 features, 16 groups => 1 feature per group
  // So reshape from (16, 16) to (16, 16, 1)
  %gn_reshaped = stablehlo.reshape %biased_result : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean across last dimension (features_per_group)
  // Mean shape will be (16, 16)
  %mean_init = stablehlo.broadcast_in_dim %c0 : (tensor<f32>) -> tensor<16x16xf32>
  %mean = "stablehlo.reduce"(%gn_reshaped, %mean_init) ({
    ^bb0(%arg6: tensor<f32>, %arg7: tensor<f32>):
      %reduce_sum = stablehlo.add %arg6, %arg7 : tensor<f32>
      "stablehlo.return"(%reduce_sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Divide by number of elements in reduction (1)
  %mean_final = stablehlo.divide %mean, %c1 : tensor<16x16xf32>

  // Broadcast mean back to original shape for variance calculation
  %mean_broadcasted = stablehlo.reshape %mean_final : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute variance: E[(x - mean)^2]
  %mean_for_variance = stablehlo.broadcast_in_dim %mean_final : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff_from_mean = stablehlo.subtract %gn_reshaped, %mean_for_variance : tensor<16x16x1xf32>
  %squared_diff = stablehlo.multiply %diff_from_mean, %diff_from_mean : tensor<16x16x1xf32>

  %variance_init = stablehlo.broadcast_in_dim %c0 : (tensor<f32>) -> tensor<16x16xf32>
  %variance_sum = "stablehlo.reduce"(%squared_diff, %variance_init) ({
    ^bb0(%arg8: tensor<f32>, %arg9: tensor<f32>):
      %reduce_sum_var = stablehlo.add %arg8, %arg9 : tensor<f32>
      "stablehlo.return"(%reduce_sum_var) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Divide by number of elements in reduction (1)
  %variance = stablehlo.divide %variance_sum, %c1 : tensor<16x16xf32>

  // Add epsilon
  %variance_eps = stablehlo.add %variance, %c_epsilon : tensor<16x16xf32>

  // Compute 1/sqrt(variance + eps)
  %sqrt_variance = stablehlo.sqrt %variance_eps : tensor<16x16xf32>
  %inv_std = stablehlo.divide %c1, %sqrt_variance : tensor<16x16xf32>

  // Normalize: (x - mean) * inv_std
  %normalized = stablehlo.subtract %biased_result, %mean_final : tensor<16x16xf32>
  %normalized_scaled = stablehlo.multiply %normalized, %inv_std : tensor<16x16xf32>

  // Apply weight and bias: normalized * weight + bias
  %weight_broadcasted = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %weighted = stablehlo.multiply %normalized_scaled, %weight_broadcasted : tensor<16x16xf32>
  %bias_gn_broadcasted = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %final_result = stablehlo.add %weighted, %bias_gn_broadcasted : tensor<16x16xf32>

  return %final_result : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<6x7x3x3xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x6x2x2xf32> {
