func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  %cst = stablehlo.constant dense<0.0> : tensor<f32>
  %cst_0 = stablehlo.constant dense<1.0> : tensor<f32>

  // Step 1: Matrix multiplication - x @ matmul.weight.T + matmul.bias
  // x has shape (16, 16), weight has shape (16, 16)
  // For Linear layer: y = x @ W^T + b
  %transpose_weight = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %matmul_result = "stablehlo.dot_general"(%arg5, %transpose_weight) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %broadcast_bias = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %add_bias_result = stablehlo.add %matmul_result, %broadcast_bias : tensor<16x16xf32>

  // Step 2: Swish activation - sigmoid(x) * x
  %neg_result = stablehlo.negate %add_bias_result : tensor<16x16xf32>
  %exp_neg_result = stablehlo.exponential %neg_result : tensor<16x16xf32>
  %add_exp = stablehlo.add %exp_neg_result, %cst_0 : tensor<16x16xf32>
  %reciprocal = stablehlo.divide %cst_0, %add_exp : tensor<16x16xf32>
  %swish_result = stablehlo.multiply %add_bias_result, %reciprocal : tensor<16x16xf32>

  // Step 3: Add bias term
  %broadcast_external_bias = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %add_external_bias = stablehlo.add %swish_result, %broadcast_external_bias : tensor<16x16xf32>

  // Step 4: Group normalization with batch statistics
  // GroupNorm with num_groups=16 means we normalize each group independently
  // With 16 channels and 16 groups, each group has 1 channel
  // Reshape to treat each sample independently: (16, 16) -> (16, 1, 16)
  %reshape_for_norm = "stablehlo.reshape"(%add_external_bias) : (tensor<16x16xf32>) -> tensor<16x1x16xf32>

  // Calculate mean for each sample (axis=2)
  %reduce_mean_init = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%reshape_for_norm, %reduce_mean_init) ({ ^bb0(%arg6: tensor<f32>, %arg7: tensor<f32>): %sum = stablehlo.add %arg6, %arg7 : tensor<f32> stablehlo.return %sum : tensor<f32> }) {dimensions = array<i64: 2>} : (tensor<16x1x16xf32>, tensor<f32>) -> tensor<16x1xf32>
  %cst_16 = stablehlo.constant dense<16.0> : tensor<f32>
  %mean_val = stablehlo.divide %mean, %cst_16 : tensor<16x1xf32>

  // Calculate variance for each sample
  %broadcast_mean = "stablehlo.broadcast_in_dim"(%mean_val) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x1xf32>) -> tensor<16x1x16xf32>
  %centered = stablehlo.subtract %reshape_for_norm, %broadcast_mean : tensor<16x1x16xf32>
  %squared = stablehlo.multiply %centered, %centered : tensor<16x1x16xf32>
  %variance = "stablehlo.reduce"(%squared, %reduce_mean_init) ({ ^bb0(%arg8: tensor<f32>, %arg9: tensor<f32>): %sum_1 = stablehlo.add %arg8, %arg9 : tensor<f32> stablehlo.return %sum_1 : tensor<f32> }) {dimensions = array<i64: 2>} : (tensor<16x1x16xf32>, tensor<f32>) -> tensor<16x1xf32>
  %variance_val = stablehlo.divide %variance, %cst_16 : tensor<16x1xf32>

  // Normalize
  %epsilon = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %var_plus_eps = stablehlo.add %variance_val, %epsilon : tensor<16x1xf32>
  %std_dev = stablehlo.rsqrt %var_plus_eps : tensor<16x1xf32>
  %broadcast_std = "stablehlo.broadcast_in_dim"(%std_dev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x1xf32>) -> tensor<16x1x16xf32>
  %normalized = stablehlo.multiply %centered, %broadcast_std : tensor<16x1x16xf32>

  // Apply weight and bias
  %reshape_normalized = "stablehlo.reshape"(%normalized) : (tensor<16x1x16xf32>) -> tensor<16x16xf32>
  %broadcast_gn_weight = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %broadcast_gn_bias = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %scale = stablehlo.multiply %reshape_normalized, %broadcast_gn_weight : tensor<16x16xf32>
  %final_result = stablehlo.add %scale, %broadcast_gn_bias : tensor<16x16xf32>

  return %final_result : tensor<16x16xf32>
}

