  %variance_sum = "stablehlo.reduce"(%diff_squared, %cst) ({ ^bb0(%arg7: tensor<f32>, %arg8: tensor<f32>): 
    %variance_sum_inner = stablehlo.add %arg7, %arg8 : tensor<f32>
    stablehlo.return %variance_sum_inner : tensor<f32>
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %variance = stablehlo.divide %variance_sum, %cst_1 : tensor<7xf32>  // Divide by 6 (batch size)

