  %std_dev_broadcast = "stablehlo.broadcast_in_dim"(%std_dev) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %normalized = stablehlo.divide %diff, %std_dev_broadcast : tensor<6x7xf32>

  // Scale and shift
  %scale = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %shift = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %normalized, %scale : tensor<6x7xf32>
  %batch_norm_out = stablehlo.add %scaled, %shift : tensor<6x7xf32>

