    %scale2_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x16x15x6x6xf32>
    %result = "stablehlo.multiply"(%biased, %scale2_broadcast) : (tensor<6x16x15x6x6xf32>, tensor<6x16x15x6x6xf32>) -> tensor<6x16x15x6x6xf32>

    return %result : tensor<6x16x15x6x6xf32>
  }
}

func.func @main(%arg0: tensor<6x7x7xf32>, %arg1: tensor<6x7x7xf32>, %arg2: tensor<16x6x7x7xf32>) -> tensor<16x6x7x7xf32> {
  %cst = "stablehlo.constant"() {value = dense<1.000000e-05> : tensor<f32>} : () -> tensor<f32>
  %cst_0 = "stablehlo.constant"() {value = dense<0.000000e+00> : tensor<f32>} : () -> tensor<f32>

  // Compute mean: reduce over last 3 dimensions (dims 1, 2, 3)
  %0 = "stablehlo.reduce"(%arg2, %cst_0) ({
  ^bb0(%arg3: tensor<f32>, %arg4: tensor<f32>):
    %9 = "stablehlo.add"(%arg3, %arg4) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    "stablehlo.return"(%9) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1, 2, 3>} : (tensor<16x6x7x7xf32>, tensor<f32>) -> tensor<16xf32>

  // Divide by number of elements (6*7*7 = 294) to get mean
  %cst_1 = "stablehlo.constant"() {value = dense<294.000000e+00> : tensor<f32>} : () -> tensor<f32>
