  %4 = "stablehlo.multiply"(%3, %3) : (tensor<16x6x7x7xf32>, tensor<16x6x7x7xf32>) -> tensor<16x6x7x7xf32>

  %5 = "stablehlo.reduce"(%4, %cst_0) ({
  ^bb0(%arg3: tensor<f32>, %arg4: tensor<f32>):
    %9 = "stablehlo.add"(%arg3, %arg4) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    "stablehlo.return"(%9) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1, 2, 3>} : (tensor<16x6x7x7xf32>, tensor<f32>) -> tensor<16xf32>

  %6 = "stablehlo.divide"(%5, %cst_1) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>

  // Broadcast variance back to original shape
  %7 = "stablehlo.broadcast_in_dim"(%6) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x6x7x7xf32>

  // Add epsilon to variance
  %8 = "stablehlo.broadcast_in_dim"(%cst) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<16x6x7x7xf32>
  %9 = "stablehlo.add"(%7, %8) : (tensor<16x6x7x7xf32>, tensor<16x6x7x7xf32>) -> tensor<16x6x7x7xf32>

  // Compute 1 / sqrt(variance + epsilon)
  %10 = "stablehlo.sqrt"(%9) : (tensor<16x6x7x7xf32>) -> tensor<16x6x7x7xf32>
  %11 = "stablehlo.divide"(%8, %10) : (tensor<16x6x7x7xf32>, tensor<16x6x7x7xf32>) -> tensor<16x6x7x7xf32>

  // Compute normalized = (x - mean) * rsqrt(variance + epsilon)
  %12 = "stablehlo.multiply"(%3, %11) : (tensor<16x6x7x7xf32>, tensor<16x6x7x7xf32>) -> tensor<16x6x7x7xf32>

  // Apply weight and bias: normalized * weight + bias
  %13 = "stablehlo.multiply"(%12, %arg0) : (tensor<16x6x7x7xf32>, tensor<6x7x7xf32>) -> tensor<16x6x7x7xf32>
  %14 = "stablehlo.add"(%13, %arg1) : (tensor<16x6x7x7xf32>, tensor<6x7x7xf32>) -> tensor<16x6x7x7xf32>

