  %product = stablehlo.multiply %arg1, %diff : tensor<12x12xf32>

  // Sum all elements (reduce across all dimensions)
  %sum = stablehlo.reduce(%product) init(%cst_0) across dimensions = [0, 1] : (tensor<12x12xf32>, tensor<f32>) -> tensor<f32>
