}

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // Step 1: Linear transformation - x @ fc.weight.T + fc.bias
  // arg4 shape: [16, 16] - input
  // arg0 shape: [16, 16] - fc.weight
  // arg1 shape: [16] - fc.bias
  %cst = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %linear = stablehlo.dot_general %arg4, %arg0, contracting_dims = [1] x [1] : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %bias_broadcasted = stablehlo.broadcast_in_dim %arg1, dims = [1] : (tensor<16xf32>) -> tensor<1x16xf32>
  %linear_with_bias = stablehlo.add %linear, %bias_broadcasted : tensor<16x16xf32>

  // Step 2: Group Normalization
  // With 16 groups and 16 channels, each group has 1 channel
  // Reshape to [16, 16, 1] to treat each channel separately
  %gn_reshape = stablehlo.reshape %linear_with_bias : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Calculate mean for each sample-channel pair
  %mean_reduce = stablehlo.reduce(%gn_reshape, %cst_0), dimensions = [2], body = {
  ^bb0(%arg_reduce1: tensor<f32>, %arg_reduce2: tensor<f32>):
    %reduce_add = stablehlo.add %arg_reduce1, %arg_reduce2 : tensor<f32>
    stablehlo.return %reduce_add : tensor<f32>
  } : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  %cst_0 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean_divisor = stablehlo.constant dense<1.000000e+00> : tensor<f32>
  %mean = stablehlo.divide %mean_reduce, %mean_divisor : tensor<16x16xf32>
  %mean_expanded = stablehlo.reshape %mean : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Calculate variance
  %mean_broadcast = stablehlo.broadcast_in_dim %mean, dims = [0, 1] : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %mean_reshaped_for_sub = stablehlo.reshape %mean_broadcast : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %gn_reshape, %mean_reshaped_for_sub : tensor<16x16x1xf32>
  %squared_diff = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %variance_reduce = stablehlo.reduce(%squared_diff, %cst_0), dimensions = [2], body = {
  ^bb0(%arg_reduce1: tensor<f32>, %arg_reduce2: tensor<f32>):
    %reduce_add = stablehlo.add %arg_reduce1, %arg_reduce2 : tensor<f32>
    stablehlo.return %reduce_add : tensor<f32>
  } : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  %variance = stablehlo.divide %variance_reduce, %mean_divisor : tensor<16x16xf32>

  // Add epsilon and take sqrt for standard deviation
  %variance_plus_eps = stablehlo.add %variance, %cst : tensor<16x16xf32>
  %std_dev = stablehlo.sqrt %variance_plus_eps : tensor<16x16xf32>

  // Normalize
  %normalized = stablehlo.divide %diff, stablehlo.reshape %std_dev : (tensor<16x16x1xf32>, tensor<16x16x1xf32>) -> tensor<16x16x1xf32>
  %normalized_reshaped = stablehlo.reshape %normalized : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply weight and bias: gamma * normalized + beta
  %weight_broadcast = stablehlo.broadcast_in_dim %arg2, dims = [1] : (tensor<16xf32>) -> tensor<1x16xf32>
  %beta_broadcast = stablehlo.broadcast_in_dim %arg3, dims = [1] : (tensor<16xf32>) -> tensor<1x16xf32>
  %scaled = stablehlo.multiply %normalized_reshaped, %weight_broadcast : tensor<16x16xf32>
  %gn_output = stablehlo.add %scaled, %beta_broadcast : tensor<16x16xf32>

  // Step 3: Leaky ReLU
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %alpha = stablehlo.constant dense<1.000000e-02> : tensor<f32>
  %zero_tensor = stablehlo.broadcast_in_dim %zero, dims = [] : (tensor<f32>) -> tensor<16x16xf32>
  %alpha_tensor = stablehlo.broadcast_in_dim %alpha, dims = [] : (tensor<f32>) -> tensor<16x16xf32>
  %negative_part = stablehlo.multiply %gn_output, %alpha_tensor : tensor<16x16xf32>
  %leaky_relu_compare = stablehlo.compare %gn_output, %zero_tensor, comparison_direction = GE : tensor<16x16xi1>
  %leaky_relu_output = stablehlo.select %leaky_relu_compare, %gn_output, %negative_part : tensor<16x16xf32>

  // Step 4: Element-wise sum (x + x)
  %final_output = stablehlo.add %leaky_relu_output, %leaky_relu_output : tensor<16x16xf32>

  return %final_output : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // Linear layer: x @ fc.weight.T + fc.bias
  %c_epsilon = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %c_neg_slope = stablehlo.constant dense<1.000000e-02> : tensor<f32>
  %c_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %c_one = stablehlo.constant dense<1.0> : tensor<f32>

  // Matrix multiplication: x @ fc.weight.T
  // arg4 is (16x16), arg0 is (16x16), we want (16x16) @ (16x16) -> (16x16)
  %fc_result = "stablehlo.dot_general"(%arg4, %arg0) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias: broadcast arg1 from (16,) to (16x16) along dim 1
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %fc_bias_result = stablehlo.add %fc_result, %bias_broadcast : tensor<16x16xf32>

  // Group Normalization: 16 groups, 16 channels => 1 channel per group
  // Reshape to separate groups: (16, 16) -> (16, 16, 1) to treat each channel separately
  %gn_reshape = stablehlo.reshape %fc_bias_result : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Calculate mean over last dimension (channel): reduce dims [2]
  %mean_init = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%gn_reshape, %mean_init) ({
    ^bb0(%lhs: tensor<f32>, %rhs: tensor<f32>):
      %sum = stablehlo.add %lhs, %rhs : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Divide by size (1) to get actual mean - since size is 1, mean equals the value
  %c_channel_size = stablehlo.constant dense<1.0> : tensor<f32>
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Calculate variance: (x - mean)^2
  %mean_reshaped = stablehlo.reshape %mean : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %gn_reshape, %mean_reshaped : tensor<16x16x1xf32>
  %diff_squared = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>

  %var_init = stablehlo.constant dense<0.0> : tensor<f32>
  %variance = "stablehlo.reduce"(%diff_squared, %var_init) ({
    ^bb0(%lhs: tensor<f32>, %rhs: tensor<f32>):
      %sum = stablehlo.add %lhs, %rhs : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Since we're dividing by 1, variance remains the same
  %variance_broadcast = "stablehlo.broadcast_in_dim"(%variance) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %epsilon_broadcast = "stablehlo.broadcast_in_dim"(%c_epsilon) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16x1xf32>
  %var_plus_eps = stablehlo.add %variance_broadcast, %epsilon_broadcast : tensor<16x16x1xf32>
  %std_dev = stablehlo.sqrt %var_plus_eps : tensor<16x16x1xf32>
  %normalized = stablehlo.divide %diff, %std_dev : tensor<16x16x1xf32>

  // Reshape back to original shape
  %normalized_reshape = stablehlo.reshape %normalized : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply weight and bias: gamma * normalized + beta
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_broadcast_gn = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %scaled = stablehlo.multiply %normalized_reshape, %weight_broadcast : tensor<16x16xf32>
  %shifted = stablehlo.add %scaled, %bias_broadcast_gn : tensor<16x16xf32>

