  %leaky_relu_result = stablehlo.maximum %shifted, %negative_scaled : tensor<16x16xf32>

  // Element-wise sum: x + x
  %final_result = stablehlo.add %leaky_relu_result, %leaky_relu_result : tensor<16x16xf32>

  return %final_result : tensor<16x16xf32>
}

