}

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // Linear layer: x @ fc.weight.T + fc.bias
  // arg4 shape: [16, 16] - input
  // arg0 shape: [16, 16] - fc.weight
  // arg1 shape: [16] - fc.bias

  // Matrix multiplication: arg4 @ arg0^T
  %transpose = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %matmul = "stablehlo.dot_general"(%arg4, %transpose) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %linear_output = "stablehlo.add"(%matmul, %bias_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Group Normalization with 16 groups, 16 channels (1 channel per group)
  // Reshape to separate groups: [16, 16] -> [16, 16, 1] (batch, groups, channels_per_group)
  %reshape_for_gn = "stablehlo.reshape"(%linear_output) : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Calculate mean and variance for each group
  // Mean calculation
  %zero_f32 = "stablehlo.constant"() {value = 0.0 : f32} : () -> tensor<f32>
  %mean = "stablehlo.reduce"(%reshape_for_gn, %zero_f32) ({
  ^bb0(%arg: tensor<f32>, %acc: tensor<f32>):
    %add = "stablehlo.add"(%arg, %acc) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  %channel_count = "stablehlo.constant"() {value = 1.0 : f32} : () -> tensor<f32>
  %mean_normalized = "stablehlo.divide"(%mean, %channel_count) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Variance calculation
  %mean_expanded = "stablehlo.broadcast_in_dim"(%mean_normalized) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = "stablehlo.subtract"(%reshape_for_gn, %mean_expanded) : (tensor<16x16x1xf32>, tensor<16x16x1xf32>) -> tensor<16x16x1xf32>
  %diff_squared = "stablehlo.multiply"(%diff, %diff) : (tensor<16x16x1xf32>, tensor<16x16x1xf32>) -> tensor<16x16x1xf32>

  %variance = "stablehlo.reduce"(%diff_squared, %zero_f32) ({
  ^bb0(%arg: tensor<f32>, %acc: tensor<f32>):
    %add = "stablehlo.add"(%arg, %acc) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  %variance_normalized = "stablehlo.divide"(%variance, %channel_count) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Add epsilon (1e-5)
  %epsilon = "stablehlo.constant"() {value = 1.0E-5 : f32} : () -> tensor<f32>
  %variance_eps = "stablehlo.add"(%variance_normalized, %epsilon) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Calculate standard deviation
  %std_dev = "stablehlo.sqrt"(%variance_eps) : (tensor<16x16xf32>) -> tensor<16x16xf32>

  // Normalize
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_normalized) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %centered = "stablehlo.subtract"(%reshape_for_gn, %mean_broadcast) : (tensor<16x16x1xf32>, tensor<16x16x1xf32>) -> tensor<16x16x1xf32>

  %std_dev_broadcast = "stablehlo.broadcast_in_dim"(%std_dev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %normalized = "stablehlo.divide"(%centered, %std_dev_broadcast) : (tensor<16x16x1xf32>, tensor<16x16x1xf32>) -> tensor<16x16x1xf32>

  // Reshape back to original shape
  %normalized_reshaped = "stablehlo.reshape"(%normalized) : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply weight and bias: gamma * normalized + beta
  %gamma_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %weighted = "stablehlo.multiply"(%normalized_reshaped, %gamma_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  %beta_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gn_output = "stablehlo.add"(%weighted, %beta_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Leaky ReLU with negative_slope = 0.01
  %zero = "stablehlo.constant"() {value = 0.0 : f32} : () -> tensor<f32>
  %zero_tensor = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x16xf32>
  %slope = "stablehlo.constant"() {value = 0.01 : f32} : () -> tensor<f32>
  %slope_tensor = "stablehlo.broadcast_in_dim"(%slope) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x1

func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
  // %arg0 = log(predictions)
  // %arg1 = targets

  // Compute log(targets)
  %log_targets = "stablehlo.log"(%arg1) : (tensor<12x12xf32>) -> tensor<12x12xf32>

  // Compute log(targets) - log(predictions)
  %diff = "stablehlo.subtract"(%log_targets, %arg0) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Compute targets * (log(targets) - log(predictions))
  %product = "stablehlo.multiply"(%arg1, %diff) : (tensor<12x12xf32>, tensor<12x12xf32>) -> tensor<12x12xf32>

  // Sum all elements to get the total KL divergence
  %zero = "stablehlo.constant"() {value = 0.0 : f32} : () -> tensor<f32>
  %sum = "stablehlo.reduce"(%product, %zero) ({
  ^bb0(%arg2: tensor<f32>, %arg3: tensor<f32>):
    %sum_inner = "stablehlo.add"(%arg2, %arg3) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    "stablehlo.return"(%sum_inner) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 1>} : (tensor<12x12xf32>, tensor<f32>) -> tensor<f32>

  // Divide by batch size (12) to get batchmean
  %batch_size = "stablehlo.constant"() {value = 12.0 : f32} : () -> tensor<f32>
  %result = "stablehlo.divide"(%sum, %batch_size) : (tensor<f32>, tensor<f32>) -> tensor<f32>

  return %result : tensor<f32>
}

func.func @main(%idx: tensor<4xi32>) -> tensor<4x8xf32> {
