func.func @main(%idx: tensor<4xi32>) -> tensor<4x8xf32> {
  %c0_i32 = arith.constant 0 : i32
  %c7_i32 = arith.constant 7 : i32
  %c0_f32 = arith.constant 0.0 : f32
  %c1_f32 = arith.constant 1.0 : f32

  // Create iota for column indices [0, 1, 2, 3, 4, 5, 6, 7]
  %iota = stablehlo.iota dim = 1 : tensor<4x8xi32>

  // Broadcast idx to shape [4, 8] - each row contains the same value repeated 8 times
  %idx_broadcast = stablehlo.broadcast_in_dim %idx, dims = [0] : (tensor<4xi32>) -> tensor<4x8xi32>

  // Compare idx_broadcast with iota to get boolean mask
  %equal = stablehlo.compare EQ, %idx_broadcast, %iota : (tensor<4x8xi32>, tensor<4x8xi32>) -> tensor<4x8xi1>

  // Check if idx values are within valid range [0, 7]
  %idx_ge_0 = stablehlo.compare GE, %idx, %c0_i32 : (tensor<4xi32>, i32) -> tensor<4xi1>
  %idx_le_7 = stablehlo.compare LE, %idx, %c7_i32 : (tensor<4xi32>, i32) -> tensor<4xi1>
  %valid_range = stablehlo.and %idx_ge_0, %idx_le_7 : tensor<4xi1>

  // Broadcast validity mask to [4, 8]
  %valid_range_broadcast = stablehlo.broadcast_in_dim %valid_range, dims = [0] : (tensor<4xi1>) -> tensor<4x8xi1>

  // Combine equality condition with range validity
  %condition = stablehlo.and %equal, %valid_range_broadcast : tensor<4x8xi1>

  // Select values based on condition: 1.0 where true, 0.0 where false
  %result = stablehlo.select %condition, %c1_f32, %c0_f32 : tensor<4x8xi1>, tensor<f32>, tensor<f32>

  return %result : tensor<4x8xf32>
}

func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c1 = stablehlo.constant dense<1.0> : tensor<f32>

  // Compute log(predictions) - this is done outside in PyTorch but we need to do it here
  // Actually wait, arg0 is already the input to the function, and from the problem statement
  // %arg0 = forward input 0; %arg1 = forward input 1
  // And the PyTorch code shows get_inputs returns [predictions.softmax(), targets.softmax()]
  // But the kl_div call is kl_div(torch.log(predictions), targets, ...)
  // So arg0 should be predictions (before log), arg1 should be targets

  // Compute log(arg0) 
  %log_pred = stablehlo.log %arg0 : tensor<12x12xf32>

  // Compute log(arg1) 
  %log_target = stablehlo.log %arg1 : tensor<12x12xf32>

  // Compute log(target) - log(prediction) = log(target/prediction)
  %log_ratio = stablehlo.subtract %log_target, %log_pred : tensor<12x12xf32>

  // Compute target * (log(target) - log(prediction))
  %kl_elements = stablehlo.multiply %arg1, %log_ratio : tensor<12x12xf32>

  // Sum all elements to get the total KL divergence
  %total_kl = "stablehlo.reduce"(%kl_elements, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 0, 1>} : (tensor<12x12xf32>, tensor<f32>) -> tensor<f32>

  // Divide by batch size (12) to get batchmean
  %batch_size = stablehlo.constant dense<12.0> : tensor<f32>
  %result = stablehlo.divide %total_kl, %batch_size : tensor<f32>

  return %result : tensor<f32>
}

