  // Apply tanh
  %5 = stablehlo.tanh %4 : tensor<6x16x16x7x7xf32>

  // Broadcast bias to match shape
  %6 = "stablehlo.broadcast_in_dim"(%arg1) {
    broadcast_dimensions = array<i64: 1, 2, 3, 4>
  } : (tensor<16x1x1x1xf32>) -> tensor<6x16x16x7x7xf32>

