module @cross_entropy_loss {
  func.func @main(%arg0: tensor<6x7xf32>, %arg1: tensor<6xi64>) -> tensor<f32> {
    // Define constants
    %cst_neg_inf = stablehlo.constant dense<"-inf"> : tensor<f32>
    %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
    %cst_one_f32 = stablehlo.constant dense<1.0> : tensor<f32>
    %cst_one_i32 = stablehlo.constant dense<1> : tensor<i32>
    %cst_zero_i32 = stablehlo.constant dense<0> : tensor<i32>
    %cst_batch_size = stablehlo.constant dense<6.0> : tensor<f32>
    %cst_num_classes = stablehlo.constant dense<7> : tensor<i32>

    // Convert targets to i32 for processing
    %targets_i32 = stablehlo.convert %arg1 : (tensor<6xi64>) -> tensor<6xi32>

    // Create one-hot encodings for targets
    // First create iota for class indices: [0, 1, 2, 3, 4, 5, 6]
    %class_indices = stablehlo.iota dim = 1 : tensor<7xi32>

    // Reshape targets to broadcast with class indices
    %targets_reshaped = stablehlo.reshape(%targets_i32) : (tensor<6xi32>) -> tensor<6x1xi32>
    %class_indices_reshaped = stablehlo.reshape(%class_indices) : (tensor<7xi32>) -> tensor<1x7xi32>

    // Compare to create one-hot encodings
    %one_hot_pred = stablehlo.compare %targets_reshaped, %class_indices_reshaped, EQ : (tensor<6x1xi32>, tensor<1x7xi32>) -> tensor<6x7xi1>

    // Convert one-hot to f32
    %one_hot = stablehlo.convert %one_hot_pred : (tensor<6x7xi1>) -> tensor<6x7xf32>

    // Compute softmax of predictions
    // For numerical stability, subtract max from each row
    %max_vals = "stablehlo.reduce"(%arg0, %cst_neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %max : tensor<f32>
    }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

    %max_broadcast = stablehlo.broadcast_in_dim %max_vals, dims = [0] : (tensor<6xf32>) -> tensor<6x7xf32>
    %shifted_logits = stablehlo.subtract %arg0, %max_broadcast : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Compute exponentials
    %exp_logits = stablehlo.exponential %shifted_logits : (tensor<6x7xf32>) -> tensor<6x7xf32>

    // Compute sum of exponentials for each row
    %sum_exp = "stablehlo.reduce"(%exp_logits, %cst_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
    }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

    // Broadcast sum and divide to get softmax
    %sum_exp_broadcast = stablehlo.broadcast_in_dim %sum_exp, dims = [0] : (tensor<6xf32>) -> tensor<6x7xf32>
    %softmax_probs = stablehlo.divide %exp_logits, %sum_exp_broadcast : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Compute cross entropy loss
    // For each sample, we want -log(softmax_probs[target_class])
    // Using one-hot encoding: loss = -sum(one_hot * log(softmax_probs))

    // Add small epsilon to prevent log(0)
    %epsilon = stablehlo.constant dense<1e-07> : tensor<f32>
    %epsilon_broadcast = stablehlo.broadcast_in_dim %epsilon, dims = [] : (tensor<f32>) -> tensor<6x7xf32>
    %softmax_clipped = stablehlo.maximum %softmax_probs, %epsilon_broadcast : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Compute log of softmax probabilities
    %log_softmax = stablehlo.log %softmax_clipped : (tensor<6x7xf32>) -> tensor<6x7xf32>

    // Multiply by one-hot to select only target class probabilities
    %selected_log_probs = stablehlo.multiply %one_hot, %log_softmax : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Sum over classes to get per-sample losses (negative log likelihood)
    %sample_losses = "stablehlo.reduce"(%selected_log_probs, %cst_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
    }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

    // Negate to get positive losses
    %positive_losses = stablehlo.negate %sample_losses : (tensor<6xf32>) -> tensor<6xf32>

    // Compute mean loss across batch
    %total_loss = "stablehlo.reduce"(%positive_losses, %cst_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
    }) {dimensions = array<i64: 0>} : (tensor<6xf32>, tensor<f32>) -> tensor<f32>

    %mean_loss = stablehlo.divide %total_loss, %cst_batch_size : (tensor<f32>, tensor<f32>) -> tensor<f32>

    return %mean_loss : tensor<f32>
  }
}

