func.func @main(%arg0: tensor<16x16x16x16xf32>) -> tensor<16x16x1x1xf32> {
  // Create initial value for reduction (0.0)
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>

  // Perform windowed sum reduction using reduce_window
  // Window dimensions: [1, 1, 11, 11] (no reduction for batch and channel dims)
  // Window strides: [1, 1, 1, 1] (we want to pool the entire spatial dimensions)
  // Since we want to go from 16x16 to 1x1 in spatial dims with kernel 11,
  // we need appropriate padding and stride

  // For kernel=11 on input size=16, to get output size=1:
  // With no padding: output_size = floor((16 - 11) / stride) + 1 = 1
  // So stride should be 5 or more. Let's use stride = 6 to center the window.
  // Actually, let's just use stride = 11 to take the whole window.
  // But that would give us floor((16-11)/11) + 1 = 1, which is correct.

  %sum = "stablehlo.reduce_window"(%arg0, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {
    window_dimensions = array<i64: 1, 1, 11, 11>,
    window_strides = array<i64: 1, 1, 1, 1>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<16x16x16x16xf32>, tensor<f32>) -> tensor<16x16x6x6xf32>

  // Wait, this doesn't match our expected output. Let me reconsider.
  // We want output shape 16x16x1x1, so we need to cover the full 16x16 spatial dimensions.
  // This means we need a larger window or appropriate padding.

  // Let's use window size 16x16 to cover the entire spatial area:
  %sum_correct = "stablehlo.reduce_window"(%arg0, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {
    window_dimensions = array<i64: 1, 1, 16, 16>,
    window_strides = array<i64: 1, 1, 1, 1>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<16x16x16x16xf32>, tensor<f32>) -> tensor<16x16x1x1xf32>

  // Now divide by the number of elements in each window to get the average
  // Each window has 16*16 = 256 elements
